'use server'

import { cookies } from 'next/headers'
import { refresh } from 'next/cache'

export async function toggleNotifications() {
  const cookieStore = await cookies()
  const enabled = cookieStore.get('notifications')?.value !== 'off'
  cookieStore.set('notifications', enabled ? 'off' : 'on')

  refresh()
}

import { cookies } from 'next/headers'
import { toggleNotifications } from './actions'

export default async function Home() {
  const cookieStore = await cookies()
  const enabled = cookieStore.get('notifications')?.value !== 'off'

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are {enabled ? 'on' : 'off'}</p>
      <form action={toggleNotifications}>
        <button type="submit">
          {enabled ? 'Turn notifications off' : 'Turn notifications on'}
        </button>
      </form>
    </main>
  )
}

export const metadata = {
  title: 'Settings',
}

export default function RootLayout({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}
